import{_ as t,c as i,o as n,ag as o}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"What is Continuous Integration, Continous Delivery, Continous Deployment?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/CD_CI/What_is_Continuous_Integration,_Continous_Delivery,_Continous_Deployment.md","filePath":"senior_growth/CD_CI/What_is_Continuous_Integration,_Continous_Delivery,_Continous_Deployment.md"}'),a={name:"senior_growth/CD_CI/What_is_Continuous_Integration,_Continous_Delivery,_Continous_Deployment.md"};function r(s,e,l,d,c,u){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-continuous-integration-continous-delivery-continous-deployment" tabindex="-1">What is Continuous Integration, Continous Delivery, Continous Deployment? <a class="header-anchor" href="#what-is-continuous-integration-continous-delivery-continous-deployment" aria-label="Permalink to “What is Continuous Integration, Continous Delivery, Continous Deployment?”">​</a></h1><h2 id="🔹-ci-cd-concepts-continuous-integration-delivery-and-deployment" tabindex="-1">🔹 CI/CD Concepts: Continuous Integration, Delivery, and Deployment <a class="header-anchor" href="#🔹-ci-cd-concepts-continuous-integration-delivery-and-deployment" aria-label="Permalink to “🔹 CI/CD Concepts: Continuous Integration, Delivery, and Deployment”">​</a></h2><p>CI/CD is a set of <strong>practices to automate the build, testing, and delivery of software</strong>, improving quality and reducing release risk. Each part focuses on a different stage of the process.</p><hr><h2 id="_1️⃣-continuous-integration-ci" tabindex="-1">1️⃣ Continuous Integration (CI) <a class="header-anchor" href="#_1️⃣-continuous-integration-ci" aria-label="Permalink to “1️⃣ Continuous Integration (CI)”">​</a></h2><p><strong>Definition:</strong><br> Continuous Integration is the practice of <strong>frequently integrating code changes into a shared repository</strong>. Every integration triggers <strong>automated builds and tests</strong>.</p><h3 id="key-points" tabindex="-1">Key Points: <a class="header-anchor" href="#key-points" aria-label="Permalink to “Key Points:”">​</a></h3><ul><li>Integrate multiple times a day to <strong>catch conflicts early</strong>.</li><li>Run <strong>unit tests, linting, type checks</strong> automatically.</li><li>Detect bugs <strong>early in the development cycle</strong>.</li></ul><h3 id="benefits" tabindex="-1">Benefits: <a class="header-anchor" href="#benefits" aria-label="Permalink to “Benefits:”">​</a></h3><ul><li>Faster feedback to developers.</li><li>Reduced integration issues.</li><li>Maintains a <strong>stable main branch</strong>.</li></ul><p><strong>Example Flow:</strong></p><ol><li>Developer pushes code to feature branch.</li><li>CI pipeline runs: <ul><li>Linting</li><li>Unit tests</li><li>Type checking</li><li>Build</li></ul></li><li>Feedback is provided automatically.</li></ol><hr><h2 id="_2️⃣-continuous-delivery-cd" tabindex="-1">2️⃣ Continuous Delivery (CD) <a class="header-anchor" href="#_2️⃣-continuous-delivery-cd" aria-label="Permalink to “2️⃣ Continuous Delivery (CD)”">​</a></h2><p><strong>Definition:</strong><br> Continuous Delivery ensures that changes are kept in a releasable state through the delivery process; the production release decision remains explicit and need not be automatic.</p><h3 id="key-points-1" tabindex="-1">Key Points: <a class="header-anchor" href="#key-points-1" aria-label="Permalink to “Key Points:”">​</a></h3><ul><li>Build, test, and prepare code for <strong>staging or production</strong>.</li><li>Deployment to production is <strong>controlled</strong>, not automatic.</li><li>Focus is on <strong>reliability and readiness</strong>.</li></ul><h3 id="benefits-1" tabindex="-1">Benefits: <a class="header-anchor" href="#benefits-1" aria-label="Permalink to “Benefits:”">​</a></h3><ul><li>Reduces manual steps in release.</li><li>Ensures <strong>production-ready builds</strong> at all times.</li><li>Minimizes risk of deployment failures.</li></ul><p><strong>Example Flow:</strong></p><ol><li>CI pipeline passes.</li><li>Build artifacts are deployed to <strong>staging environment</strong>.</li><li>The authorized release decision triggers the tested automated deployment; delivery does not require a person to copy files.</li></ol><hr><h2 id="_3️⃣-continuous-deployment-cd" tabindex="-1">3️⃣ Continuous Deployment (CD) <a class="header-anchor" href="#_3️⃣-continuous-deployment-cd" aria-label="Permalink to “3️⃣ Continuous Deployment (CD)”">​</a></h2><p><strong>Definition:</strong><br> Continuous Deployment takes Continuous Delivery <strong>one step further</strong>: eligible changes that pass the complete configured release gates are automatically deployed to production.</p><h3 id="key-points-2" tabindex="-1">Key Points: <a class="header-anchor" href="#key-points-2" aria-label="Permalink to “Key Points:”">​</a></h3><ul><li>No manual approval is needed.</li><li>Strong automated testing and monitoring is required.</li><li>Focus is on <strong>rapid and safe delivery</strong>.</li></ul><h3 id="benefits-2" tabindex="-1">Benefits: <a class="header-anchor" href="#benefits-2" aria-label="Permalink to “Benefits:”">​</a></h3><ul><li>Immediate delivery of new features and fixes.</li><li>Faster feedback from production.</li><li>Encourages <strong>small, incremental changes</strong>.</li></ul><p><strong>Example Flow:</strong></p><ol><li>CI pipeline passes.</li><li>Artifact is automatically deployed to <strong>production</strong>.</li><li>Monitoring tools check for issues; rollback if needed.</li></ol><hr><h2 id="_4️⃣-key-differences" tabindex="-1">4️⃣ Key Differences <a class="header-anchor" href="#_4️⃣-key-differences" aria-label="Permalink to “4️⃣ Key Differences”">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>CI</th><th>Continuous Delivery</th><th>Continuous Deployment</th></tr></thead><tbody><tr><td>Goal</td><td>Integrate code frequently</td><td>Ensure deployable builds</td><td>Deploy automatically</td></tr><tr><td>Deployment</td><td>Integration alone does not prescribe deployment; it can coexist with either CD policy</td><td>Explicit release decision, usually automated deployment execution</td><td>Automatic release/deployment after configured gates</td></tr><tr><td>Feedback speed</td><td>Depends on integration/check duration</td><td>Includes release-decision waiting time</td><td>Depends on gates and production observation</td></tr><tr><td>Risk</td><td>Depends on change, checks and operational controls</td><td>Depends on change, checks and operational controls</td><td>Depends on change, gates and operational controls</td></tr></tbody></table><hr><h3 id="✅-summary" tabindex="-1">✅ Summary <a class="header-anchor" href="#✅-summary" aria-label="Permalink to “✅ Summary”">​</a></h3><ul><li><strong>CI:</strong> Frequent integration + automated tests.</li><li><strong>Continuous Delivery:</strong> keep changes releasable with an explicit production release decision and repeatable deployment execution.</li><li><strong>Continuous Deployment:</strong> CI + automated deployment; code goes to production automatically.</li></ul><blockquote><p>💡 Senior Tip:<br> The <strong>main difference</strong> between Delivery and Deployment is <strong>manual vs automatic release to production</strong>. Both require <strong>strong CI and test automation</strong> to be safe.</p></blockquote><h2 id="isolated-jobs-artifact-identity-and-safe-rollback" tabindex="-1">Isolated jobs, artifact identity and safe rollback <a class="header-anchor" href="#isolated-jobs-artifact-identity-and-safe-rollback" aria-label="Permalink to “Isolated jobs, artifact identity and safe rollback”">​</a></h2><p>An earlier job&#39;s installation/worktree is not implicitly shared with later jobs. Install required tooling/dependencies from the matching lockfile in each isolated consumer, or explicitly transfer the immutable artifact and its trusted identity. A dependency cache is an optimization, not proof of the tested/released bytes. Deploy the exact artifact verified in the previous stage, with environment-specific secrets/configuration injected through controlled runtime mechanisms.</p><p>Use the <a href="./../../node-js/release-artifact-compatibility.html">executed artifact and PostgreSQL compatibility lab</a> for the primary example. It creates/verifies/extracts actual tar artifacts in distinct job directories and executes old/bridge/new SQL contracts against an isolated real database. The lesson explains the workflow inputs/gates without claiming an unexecuted hosted YAML pipeline exists.</p><p>Passing unit tests does not prove production releasability: migration compatibility, authorization/configuration, health/traffic, monitoring and recovery gates still apply. Manual approval is a release decision and can trigger an automated deployment; “manual” does not require a person copying files. Reversing traffic/artifacts is safe only while old code remains compatible with current data/messages/config. V4-only writes can close that window before a column is dropped. Retain a tested rollback allowlist or plan forward repair, not a generic “redeploy old version” promise.</p><h2 id="separate-practice" tabindex="-1">Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “Separate practice”">​</a></h2><p>Use the <a href="./../../practice/engineering/delivery/What_is_Continuous_Integration%2C_Continous_Delivery%2C_Continous_Deployment.html">focused acceptance and evidence requirements</a>. All learner practice remains outstanding.</p>',43)])])}const g=t(a,[["render",r]]);export{h as __pageData,g as default};
